const lensOnly=process.env.AGENTNET_GROUP_LENSES_ONLY==='1',tailOnly=process.env.AGENTNET_GROUP_ASSISTANT_TAIL_ONLY==='1';let browser,stage='link',pages={};const idle=ms=>new Promise(r=>setTimeout(r,ms));
const ready=p=>p.waitForFunction(()=>typeof state!=='undefined'&&state.overview);
async function until(label,f){const end=Date.now()+25000;while(Date.now()<end){if(await f())return;await idle(100);}throw Error('Timed out: '+label);}
async function click(p,l,label){await l.click();actions.push(label);}
async function capture(p,name,width){await idle(150);const overflow=await p.evaluate(()=>({document:document.documentElement.scrollWidth>innerWidth,dialogs:[...document.querySelectorAll('dialog[open]')].some(d=>d.scrollWidth>d.clientWidth+1)}));assert(!overflow.document&&!overflow.dialogs,name+' overflow');const file=path.join(evidence,name+'-'+width+'.png');await p.screenshot({path:file});shots.push(file);if(width===1280&&/^(create-|invite-|accept-|governance-|last-admin|offline-|file-|selected-history)/.test(name)){const previous=p.viewportSize();await p.setViewportSize({width:390,height:844});await capture(p,name,390);await p.setViewportSize(previous);}}
async function people(p){if(await p.locator('#dialog').isVisible())await click(p,p.locator('#dialog-cancel'),'Close dialog');if(!(await p.locator('#nav-people').isVisible()))await click(p,p.locator('#back'),'Back to conversations');await click(p,p.locator('#nav-people'),'People');}
async function openGroup(p,id){await people(p);await click(p,p.locator('#conv-list button').filter({hasText:await p.evaluate(id=>state.overview.dms.find(d=>d.id===id).title,id)}).last(),'Open exact group');await p.waitForFunction(id=>state.dm===id&&state.dmData?.id===id,id);}
async function create(p,title,width){await people(p);await click(p,p.getByRole('button',{name:'New group…',exact:true}),'New group');await p.locator('#group-name').fill(title);await capture(p,'create-'+title,width);await click(p,p.locator('#dialog-ok'),'Create group');await p.locator('#dialog').waitFor({state:'hidden'});await p.waitForFunction(title=>state.dmData?.kind==='group'&&state.dmData.title===title,title);return p.evaluate(()=>state.dm);}
async function pinPerson(p,name){await people(p);const row=p.locator('#conv-list .contact-item').filter({hasText:name});await click(p,row.locator('button.contact'),name+' person');await p.locator('#hub').waitFor({state:'visible'});const start=p.locator('#hub').getByRole('button',{name:/New DM|New conversation/}).first();if(await start.count()){await click(p,start,'Open pinned person conversation');if(await p.locator('#dialog').isVisible()){await click(p,p.locator('#dialog-ok'),'Start checked person DM');await p.locator('#dialog').waitFor({state:'hidden'});}}await people(p);}
async function invite(p,id,name,width,selected=[]){await openGroup(p,id);await click(p,p.getByRole('button',{name:'Invite a person…',exact:true}),'Invite person');const opts=await p.locator('#group-invite-person option').allTextContents();const opt=opts.find(t=>t.startsWith(name+' ·'));assert(opt,'Pinned invite person '+name+' options '+opts);await p.locator('#group-invite-person').selectOption({label:opt});if(selected.length){await p.locator('#group-history-mode').selectOption('selected');for(const text of selected)await p.locator('#dialog label').filter({hasText:text}).locator('input[type=checkbox]').check();}await capture(p,'invite-'+name,width);await click(p,p.locator('#dialog-ok'),'Send exact invitation');await p.locator('#dialog').waitFor({state:'hidden'});}
async function accept(p,title,width){await people(p);await p.locator('#conv-list').getByRole('button',{name:new RegExp('Invitation: '+title)}).waitFor();await click(p,p.locator('#conv-list').getByRole('button',{name:new RegExp('Invitation: '+title)}),'Review invitation');await capture(p,'accept-'+title,width);await click(p,p.locator('#dialog-ok'),'Accept invitation');await p.locator('#dialog').waitFor({state:'hidden'});await p.waitForFunction(title=>(state.overview.dms||[]).some(d=>d.kind==='group'&&d.title===title),title,{timeout:30000});const id=await p.evaluate(title=>state.overview.dms.find(d=>d.kind==='group'&&d.title===title).id,title);await openGroup(p,id);return id;}
const msg=(p,id)=>p.locator('#m-'+id);
async function send(p,body){await p.locator('#body').fill(body);await click(p,p.locator('#send'),'Send group text');await p.waitForFunction(body=>state.dmData.messages.some(m=>m.body===body),body);assert.equal(await p.locator('#compose-error').innerText(),'');return p.evaluate(body=>state.dmData.messages.find(m=>m.body===body),body);}
async function reply(p,parent,body){await click(p,msg(p,parent.id).getByRole('button',{name:'Reply',exact:true}),'Reply to exact logical group turn');const m=await send(p,body);assert.equal(m.reply_to,parent.lid||parent.id);return m;}
async function sendFile(p,body,name,bytes){const chooser=p.waitForEvent('filechooser');await click(p,p.locator('#attach'),'Attach exact group file');await(await chooser).setFiles({name,mimeType:'application/octet-stream',buffer:bytes});await p.locator('#attach-list').getByText(name,{exact:true}).waitFor();const m=await send(p,body);assert.equal(m.attachments[0].name,name);return m;}
async function downloadFile(p,body,name,bytes,label){await p.waitForFunction(({body,name})=>state.dmData.messages.some(m=>m.body===body&&m.attachments.some(f=>f.name===name)),{body,name});const m=await p.evaluate(({body,name})=>state.dmData.messages.find(m=>m.body===body&&m.attachments.some(f=>f.name===name)),{body,name});let file=msg(p,m.id).locator('.file').filter({hasText:name});const get=file.getByRole('button',{name:/^Get it from /});if(await get.count()){await click(p,get,'Request exact selected group file');await p.waitForFunction(({id,name})=>state.dmData.messages.find(m=>m.id===id)?.attachments.find(f=>f.name===name)?.availability!=='requested',{id:m.id,name});file=msg(p,m.id).locator('.file').filter({hasText:name});}await idle(300);await click(p,file.getByRole('button',{name:'Open',exact:true}),'Open verified group file');
 try{await file.getByRole('link',{name:'Download '+name,exact:true}).waitFor({timeout:2000});}catch(e){
  if(!(await file.getByRole('button',{name:'Open',exact:true}).isVisible()))throw e;
  await capture(p,'first-file-redraw-'+label,1280);await idle(300);await click(p,file.getByRole('button',{name:'Open',exact:true}),'Reopen file after settled redraw (no Send repeated)');await file.getByRole('link',{name:'Download '+name,exact:true}).waitFor();
 }const pending=p.waitForEvent('download');await click(p,file.getByRole('link',{name:'Download '+name,exact:true}),'Save exact group bytes');const d=await pending,filePath=path.join(world,'download-'+label);await d.saveAs(filePath);assert.deepEqual(fs.readFileSync(filePath),bytes);checks.push({gate:'exact file bytes',label,sha256:digest(bytes),size:bytes.length});await capture(p,'file-'+label,1280);}

