async function named(p,host){await click(p,p.locator('#profile-btn'),'Profile');await click(p,p.getByRole('tab',{name:'Agent',exact:true}),'Agent');await click(p,p.getByRole('button',{name:'Create agent…',exact:true}),'Create named synthetic agent');await p.locator('#named-label').fill('Synthetic '+host+' group builder');await p.locator('#named-harness').selectOption('codex');await p.locator('#named-dir').fill(path.join(world,'work-'+host));await click(p,p.locator('#dialog-ok'),'Configure exact named executor');await p.locator('#dialog').waitFor({state:'hidden'});const catalog=await p.evaluate(()=>agentnet.api('/api/agents'));assert.equal(catalog.agents.length,1);await click(p,p.locator('#settings-close'),'Close settings');return catalog.agents[0].record.id;}
