async function acceptAgent(p,pid,width){await p.waitForFunction(pid=>state.dmData.agents.some(a=>a.pid===pid&&a.state==='invited'),pid);await click(p,p.locator('#agents .agent-card.invited').getByRole('button',{name:'Accept…',exact:true}),'Accept exact host invitation');await capture(p,'group-agent-host-accept',width);await click(p,p.locator('#dialog-ok'),'Conscious host acceptance');await p.locator('#dialog').waitFor({state:'hidden'});}
async function ask(p,agentID,kind,name,bytes,body=''){const host=await p.evaluate(agentID=>state.dmData.agents.find(a=>a.agent_id===agentID).host.address,agentID);const card=p.locator('#agents .agent-card.active').filter({has:p.locator('.agent-head strong[title="'+agentID+' · '+host+'"]')});assert.equal(await card.count(),1,'exact AgentID and host visible card');await click(p,card.getByRole('button',{name:'Ask',exact:true}),'Ask exact named group agent');await p.getByRole('radio',{name:kind==='task'?'Task':'Question',exact:true}).check();if(kind==='question')assert.match(await p.locator('#compose-hint').innerText(),/Current group members see/);if(name)await p.locator('#file-input').setInputFiles({name,mimeType:'text/plain',buffer:bytes});await p.locator('#body').fill(body);await click(p,p.locator('#send'),'Send exact group '+kind);}

